package runtime

func dashboardHTML() string {
	return `<!doctype html><html><head><title>vibe-proxy</title><style>
body{margin:0;background:#08090a;color:#f4f4f5;font-family:Inter,ui-sans-serif,system-ui}.wrap{max-width:1120px;margin:48px auto;padding:24px}.card{border:1px solid #27272a;background:#111113;border-radius:18px;padding:24px;margin-bottom:16px}.muted{color:#a1a1aa}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.row{display:flex;justify-content:space-between;border-top:1px solid #27272a;padding:10px 0}.ok{color:#22c55e}.err{color:#ef4444}</style></head><body><main class="wrap"><section class="card"><p class="muted">vibe-proxy local</p><h1>Agent-first LLM protocol switcher</h1><p class="muted">Stable local endpoints for OpenAI Chat, OpenAI Responses, and Anthropic Messages.</p><div class="grid"><div><b>OpenAI Chat</b><p class="mono">/v1/chat/completions</p></div><div><b>OpenAI Responses</b><p class="mono">/v1/responses</p></div><div><b>Anthropic</b><p class="mono">/anthropic/v1/messages</p></div></div></section><section class="card"><h2>Recent requests</h2><p class="muted">Use the admin API for now:</p><p class="mono">GET /admin/requests/recent</p></section><section class="card"><h2>Runtime config</h2><p class="mono">GET /admin/config/snapshot</p><p class="mono">POST /admin/config/reload</p></section></main></body></html>`
}
